<?php
require_once __DIR__.'/includes/quality.php';
if(!is_admin()){header('Location: admin.php');exit;}
$error='';$notice='';$users=[];
try{quality_schema();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!valid_csrf($_POST['csrf_token']??null))throw new InvalidArgumentException('Recarga la página para continuar.');
 $username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'');
 if(!preg_match('/^[a-zA-Z0-9_.-]{3,60}$/',$username)||in_array(strtolower($username),[strtolower(ADMIN_USER),strtolower(TESTER_USER)],true))throw new InvalidArgumentException('Usa un nombre disponible de 3 a 60 caracteres, sin espacios.');
 if(strlen($password)<8||strlen($password)>72)throw new InvalidArgumentException('La contraseña debe tener entre 8 y 72 caracteres.');
 if(!in_array($role,['tester','admin'],true))throw new InvalidArgumentException('Rol no válido.');
 $s=db()->prepare('INSERT INTO app_users(username,password_hash,role) VALUES(?,?,?)');$s->execute([$username,password_hash($password,PASSWORD_DEFAULT),$role]);header('Location: cuentas.php?created=1');exit;
}$notice=isset($_GET['created'])?'Cuenta creada correctamente.':'';$users=db()->query('SELECT username,role,created_at FROM app_users ORDER BY id DESC')->fetchAll();
}catch(Throwable $ex){$error=$ex instanceof InvalidArgumentException?$ex->getMessage():'No se pudo crear la cuenta. Comprueba que el nombre no esté registrado.';error_log($ex->getMessage());}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cuentas | WS Bus</title><link rel="stylesheet" href="assets/css/styles.css"></head><body><header class="topbar"><a class="brand" href="admin.php">WS BUS</a><nav><a href="admin.php">Administración</a><a href="admin.php?logout=1">Cerrar sesión</a></nav></header><main class="admin-main"><p class="eyebrow">ADMINISTRACIÓN</p><h1>Cuentas de acceso</h1><p>Asigna a cada persona el acceso que necesita.</p><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?><?php if($notice):?><div class="alert success" role="status"><?= e($notice) ?></div><?php endif;?><section class="form-card"><h2>Crear cuenta</h2><form method="post" class="stack-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Usuario<input name="username" required minlength="3" maxlength="60" autocomplete="off"></label><label>Contraseña<input type="password" name="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><label>Rol<select name="role"><option value="tester">Tester · herramientas de pruebas</option><option value="admin">Administrador · catálogo y cuentas</option></select></label><button class="primary-button">Crear cuenta</button></form></section><section class="admin-section"><h2>Cuentas disponibles</h2><div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Rol</th></tr></thead><tbody><tr><td><?= e(ADMIN_USER) ?></td><td>Administrador</td></tr><tr><td><?= e(TESTER_USER) ?></td><td>Tester</td></tr><?php foreach($users as $u):?><tr><td><?= e($u['username']) ?></td><td><?= e($u['role']) ?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
